def next_smallest_palindrome(num):
    numstr = str(num)
    length = len(numstr)
    if all(c == '9' for c in numstr):
        return 10 ** length + 1
    half = numstr[:(length + 1) // 2]
    next_half = str(int(half) + 1)
    if len(next_half) > len(half):
        return 10 ** length + 1
    if length % 2 == 0:
        return int(next_half + next_half[::-1])
    else:
        return int(next_half + next_half[:-1][::-1])
```

